mapper.select:
SELECT id, name, uname, upass, upass_md5, age, email, phone, gender,
       avatar, create_time, update_time
FROM student2 WHERE id = #{stuId}

SELECT id, name, uname, upass, upass_md5, age, email, phone, gender,
       avatar, create_time, update_time
FROM student2 WHERE name like #{name}

SELECT id, name, uname, upass, upass_md5, age, email, phone, gender, avatar, create_time, update_time FROM student2
AND id = #{id}
AND name like concat('%', #{name}, '%')
AND age = #{age}
AND email like concat('%', #{email}, '%')
ORDER BY id ASC

SELECT id, name, uname, upass, upass_md5, age, email, phone, gender,
       avatar, create_time, update_time, remember_token
FROM student2 WHERE uname = #{uname}

SELECT id, name, uname, upass, upass_md5, age, email, phone, gender,
       avatar, create_time, update_time, remember_token
FROM student2 WHERE remember_token = #{token}
